import java.util.Scanner;

public class TopScore {
    static final int MOD = 998244353;
    static final int MAXN = 5100; // s up to 5000, plus some buffer
    static final int MAXP = 105;  // p up to 100

    static int[] fact = new int[MAXN];
    static int[] invFact = new int[MAXN];
    static int[] inv = new int[MAXN];

    static int modPow(int a, int e) {
        long res = 1;
        long cur = a;
        while (e > 0) {
            if ((e & 1) == 1) res = res * cur % MOD;
            cur = cur * cur % MOD;
            e >>= 1;
        }
        return (int) res;
    }

    static void precompute() {
        fact[0] = 1;
        for (int i = 1; i < MAXN; i++) fact[i] = (int)((long)fact[i-1] * i % MOD);
        invFact[MAXN-1] = modPow(fact[MAXN-1], MOD-2);
        for (int i = MAXN-2; i >= 0; i--) invFact[i] = (int)((long)invFact[i+1] * (i+1) % MOD);
        inv[1] = 1;
        for (int i = 2; i < MAXN; i++) inv[i] = (int)((long)(MOD - MOD/i) * inv[MOD%i] % MOD);
    }

    // C(n, k) modulo MOD
    static int C(int n, int k) {
        if (k < 0 || k > n) return 0;
        return (int)((long)fact[n] * invFact[k] % MOD * invFact[n-k] % MOD);
    }

    // number of ways to put sum into cnt parts, each >= 0 (standard stars and bars)
    static int ways(int sum, int cnt) {
        if (cnt == 0) return sum == 0 ? 1 : 0;
        if (sum < 0) return 0;
        return C(sum + cnt - 1, cnt - 1);
    }

    // number of ways to put sum into cnt parts, each <= maxVal (inclusion-exclusion)
    static int waysBounded(int sum, int cnt, int maxVal) {
        if (cnt == 0) return sum == 0 ? 1 : 0;
        if (sum < 0) return 0;
        int res = 0;
        for (int k = 0; k <= cnt; k++) {
            int rem = sum - k * (maxVal + 1);
            if (rem < 0) break;
            int term = (int)((long)C(cnt, k) * ways(rem, cnt) % MOD);
            if ((k & 1) == 0) {
                res += term;
                if (res >= MOD) res -= MOD;
            } else {
                res -= term;
                if (res < 0) res += MOD;
            }
        }
        return res;
    }

    public static void main(String[] args) {
        precompute();
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int s = sc.nextInt();
        int r = sc.nextInt();
        sc.close();

        // total number of valid score sequences
        int totalWays = ways(s - r, p);

        long numerator = 0;
        // iterate Hasan's actual score x from r to s
        for (int x = r; x <= s; x++) {
            int remSum = s - x;
            // number of other players with score exactly x can be k = 0..p-1
            // Hasan wins if he is among the top scorers and chosen randomly.
            // If k others have score x, total top scorers = k+1, Hasan wins with prob 1/(k+1).
            for (int k = 0; k <= p - 1; k++) {
                // choose which k players have score x: C(p-1, k)
                // remaining (p-1-k) players have score <= x-1, sum = remSum - k*x
                int waysChoose = C(p - 1, k);
                int waysRest = waysBounded(remSum - k * x, p - 1 - k, x - 1);
                int waysTotal = (int)((long)waysChoose * waysRest % MOD);
                if (waysTotal == 0) continue;
                // probability factor 1/(k+1)
                long add = (long)waysTotal * inv[k + 1] % MOD;
                numerator += add;
                if (numerator >= MOD) numerator -= MOD;
            }
        }

        int ans = (int)(numerator % MOD * modPow(totalWays, MOD - 2) % MOD);
        System.out.println(ans);
    }
}
